-- Fresh CI database fixture based on the local PostgreSQL base-table schema.
-- These synthetic accounts are only for the disposable CI database.

CREATE TABLE locaties (
  id INTEGER PRIMARY KEY,
  naam VARCHAR(100) NOT NULL,
  adres VARCHAR(100),
  postcode VARCHAR(6),
  plaats VARCHAR(50),
  telefoonnummer VARCHAR(12),
  actief BIT(1),
  idlocatie INTEGER NOT NULL UNIQUE
);

CREATE TABLE consultant (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  achternaam TEXT NOT NULL,
  email TEXT NOT NULL,
  functie TEXT,
  telefoonnummer TEXT,
  defaultlocatie INTEGER REFERENCES locaties (idlocatie),
  aanmaakdatum TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  werkdagen TEXT,
  start_werkdag TEXT,
  einde_werkdag TEXT,
  start_pauze TEXT,
  voornaam TEXT,
  tussenvoegsel TEXT,
  username VARCHAR(80) NOT NULL,
  password VARCHAR(255) NOT NULL
);

CREATE TABLE klanten (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  voornaam VARCHAR(50) NOT NULL,
  achternaam VARCHAR(50) NOT NULL,
  email VARCHAR(100) UNIQUE,
  aanmaakdatum TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW(),
  tussenvoegsel VARCHAR(255),
  telefoonnummer VARCHAR(15),
  username VARCHAR(80),
  password VARCHAR(255),
  fullname VARCHAR(125)
);

